export const buildLearningPathBodySkillMin = 2;
export const buildLearningPathBodySkillMax = 50;

export const buildLearningPathBodyGoalMax = 180;

export const buildLearningPathBodyCategoryNameMin = 2;
export const buildLearningPathBodyCategoryNameMax = 60;



export const BuildLearningPathBody = zod.object({
  "skill": zod.string().min(buildLearningPathBodySkillMin).max(buildLearningPathBodySkillMax),
  "goal": zod.string().max(buildLearningPathBodyGoalMax).optional(),
  "categoryName": zod.string().min(buildLearningPathBodyCategoryNameMin).max(buildLearningPathBodyCategoryNameMax).optional()
})

export const BuildLearningPathResponse = zod.object({
  "category": zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "iconUrl": zod.string().nullable(),
  "favorite": zod.boolean(),
  "archivedAt": zod.coerce.date().nullable(),
  "totalVideos": zod.number(),
  "watchedVideos": zod.number(),
  "progressPercent": zod.number(),
  "levelCounts": zod.object({
  "Beginner": zod.number(),
  "Intermediate": zod.number(),
  "Advanced": zod.number(),
  "Expert": zod.number()
})
}),
  "levels": zod.array(zod.object({
  "level": zod.enum(['Beginner', 'Intermediate', 'Advanced', 'Expert']),
  "playlistId": zod.string(),
  "playlistTitle": zod.string(),
  "channelName": zod.string(),
  "url": zod.string(),
  "videoCount": zod.number(),
  "note": zod.string().optional()
})),
  "totalImported": zod.number()
})


